package com.example.incidentapp.viewmodel;
import androidx.lifecycle.*; import com.example.incidentapp.model.ReporteResumen; import com.example.incidentapp.repository.ReporteRepository; import com.example.incidentapp.util.*; import retrofit2.*;
public class ReportesViewModel extends ViewModel{private final ReporteRepository repo=new ReporteRepository();private final MutableLiveData<ReporteResumen> reporte=new MutableLiveData<>();private final MutableLiveData<Boolean> loading=new MutableLiveData<>(false);private final MutableLiveData<Event<String>> error=new MutableLiveData<>();public LiveData<ReporteResumen> getReporte(){return reporte;}public LiveData<Boolean> getLoading(){return loading;}public LiveData<Event<String>> getError(){return error;}public void cargar(){loading.setValue(true);repo.obtener().enqueue(new Callback<ReporteResumen>(){public void onResponse(Call<ReporteResumen> c,Response<ReporteResumen> r){loading.setValue(false);if(r.isSuccessful()&&r.body()!=null)reporte.setValue(r.body());else error.setValue(new Event<>(ApiErrorUtils.obtenerMensaje(r,"No se pudieron cargar los reportes")));}public void onFailure(Call<ReporteResumen> c,Throwable t){loading.setValue(false);error.setValue(new Event<>("No se pudo conectar con la API"));}});}}
